begin;
do $test$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c jsonb; c2 jsonb; room uuid; sess jsonb; student uuid; denied boolean; before_rows jsonb; rows jsonb;
 label text:='MEMBER-'||upper(substr(md5(random()::text),1,10));
begin
 begin
 insert into private.faculty_approvals(email) values(a::text||'@classpulse.invalid'),(b::text||'@classpulse.invalid');
 insert into auth.users(id,email,raw_user_meta_data,is_anonymous,email_confirmed_at) values(a,a::text||'@classpulse.invalid','{"full_name":"Rooms A"}',false,now()),(b,b::text||'@classpulse.invalid','{"full_name":"Rooms B"}',false,now());
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 c:=public.classpulse_save_room(null,label);c2:=public.classpulse_save_room(null,label||'-B');
 perform public.classpulse_add_students((c->>'id')::uuid,'[{"id":"001","name":"Original Full Name","emailid":"old@classpulse.invalid"}]');
 perform public.classpulse_add_students((c2->>'id')::uuid,'[{"id":"001","name":"Original Full Name","emailid":"old@classpulse.invalid"}]');
 select id into student from public.students where teacher_id=a and student_code='001';
 select id into room from public.rooms where roster_id=(c->>'id')::uuid;
 sess:=public.classpulse_launch_quick(room,'quick_tf',2,'Snapshot question','room-management-fixture');
 select jsonb_agg(to_jsonb(s)) into before_rows from public.session_roster_students s where session_id=(sess->>'id')::uuid;
 perform public.classpulse_add_students((c->>'id')::uuid,'[{"id":"002","name":"Second Student","emailid":""}]');
 if (select count(*) from public.roster_students where roster_id=(c->>'id')::uuid and withdrawn_at is null)<>2 then raise exception 'FAIL: addition replaced roster';end if;
 denied:=false;begin perform public.classpulse_add_students((c->>'id')::uuid,'[{"id":"001","name":"Original Full Name","emailid":""}]');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: enrolled duplicate accepted';end if;
 denied:=false;begin perform public.classpulse_add_students((c->>'id')::uuid,'[{"id":"003","name":"Valid Student","emailid":""},{"id":"004","name":"Bad Email","emailid":"bad"}]');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: invalid email accepted';end if;
 if exists(select 1 from public.students where teacher_id=a and student_code='003') then raise exception 'FAIL: partial import';end if;
 denied:=false;begin perform public.classpulse_add_students((c2->>'id')::uuid,'[{"id":"002","name":"Conflicting Name","emailid":""}]');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: conflicting shared identity';end if;
 denied:=false;begin perform public.classpulse_add_students((c2->>'id')::uuid,'[{"id":"abc","name":"Same","emailid":""},{"id":"ABC","name":"Same","emailid":""}]');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: case insensitive duplicates';end if;
 perform public.classpulse_edit_student((c->>'id')::uuid,'001','New Full Name','new@classpulse.invalid','Original Full Name','old@classpulse.invalid');
 if (select full_name from public.students where id=student)<>'New Full Name' then raise exception 'FAIL: edit';end if;
 if not exists(select 1 from public.roster_students rs join public.students s on s.id=rs.student_id where rs.roster_id=(c2->>'id')::uuid and s.full_name='New Full Name') then raise exception 'FAIL: shared name edit';end if;
 denied:=false;begin perform public.classpulse_edit_student((c->>'id')::uuid,'001','Stale','', 'Original Full Name','old@classpulse.invalid');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: stale edit overwrites';end if;
 perform public.classpulse_remove_student((c->>'id')::uuid,'001');
 if exists(select 1 from public.roster_students where roster_id=(c->>'id')::uuid and student_id=student and withdrawn_at is null) then raise exception 'FAIL: removal';end if;
 if not exists(select 1 from public.roster_students where roster_id=(c2->>'id')::uuid and student_id=student and withdrawn_at is null) then raise exception 'FAIL: other room removed';end if;
 if (select jsonb_agg(to_jsonb(s)) from public.session_roster_students s where session_id=(sess->>'id')::uuid) is distinct from before_rows then raise exception 'FAIL: active snapshot changed';end if;
 perform public.classpulse_end_session((sess->>'id')::uuid);
 perform public.classpulse_add_students((c->>'id')::uuid,'[{"id":"001","name":"New Full Name","emailid":"new@classpulse.invalid"}]');
 if (select jsonb_agg(to_jsonb(s)) from public.session_roster_students s where session_id=(sess->>'id')::uuid) is distinct from before_rows then raise exception 'FAIL: saved snapshot changed';end if;
 if (select count(*) from public.students where teacher_id=a and student_code='001')<>1 then raise exception 'FAIL: reentry duplicated identity';end if;
 if not exists(select 1 from jsonb_array_elements(public.classpulse_room_list()) x where x->>'id'=c->>'id' and (x->>'student_count')::int=2) then raise exception 'FAIL: room counts';end if;
 select jsonb_agg(jsonb_build_object('id','CAP-'||i,'name','Student '||i,'emailid','')) into rows from generate_series(1,148) i;
 perform public.classpulse_add_students((c->>'id')::uuid,rows);
 denied:=false;begin perform public.classpulse_add_students((c->>'id')::uuid,'[{"id":"OVER","name":"Over Limit","emailid":""}]');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: capacity';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);
 if jsonb_array_length(public.classpulse_room_list())<>0 then raise exception 'FAIL: foreign room list';end if;
 denied:=false;begin perform public.classpulse_add_students((c->>'id')::uuid,'[{"id":"X","name":"Foreign","emailid":""}]');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: foreign add';end if;
 denied:=false;begin perform public.classpulse_edit_student((c->>'id')::uuid,'001','Foreign','','New Full Name','new@classpulse.invalid');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: foreign edit';end if;
 denied:=false;begin perform public.classpulse_remove_student((c->>'id')::uuid,'001');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: foreign remove';end if;
 execute 'reset role';update private.faculty_approvals set enabled=false where email=a::text||'@classpulse.invalid';
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 denied:=false;begin perform public.classpulse_room_list();exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: revoked faculty list';end if;
 denied:=false;begin perform public.classpulse_remove_student((c->>'id')::uuid,'001');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: revoked faculty write';end if;
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 denied:=false;begin perform public.classpulse_room_list();exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: student lists rooms';end if;
 denied:=false;begin perform public.classpulse_add_students((c->>'id')::uuid,'[]');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: student adds roster';end if;
 execute 'reset role';raise exception using errcode='CP001',message='Rollback fixtures';
 exception when sqlstate 'CP001' then null;
 end;
 if exists(select 1 from auth.users where id in(a,b)) then raise exception 'FAIL: fixtures remain';end if;
end $test$;
rollback;
select 'PASS: room additions, edits, removal, capacity, saved quiz snapshots and teacher privacy verified; fixtures rolled back' as result;

